import { useState } from "react";
import Checker from "./Checker";
import History from "./History";
import "./App.css";

function App() {
  const [tab, setTab] = useState("checker");

  return (
    <div className="app">
      <header className="header">
        <div className="logo">
          <span className="logo-icon">🔍</span>
          <h1>TruthLens</h1>
          <span className="tagline">AI Hallucination Checker</span>
        </div>
        <nav className="nav">
          <button
            className={`nav-btn ${tab === "checker" ? "active" : ""}`}
            onClick={() => setTab("checker")}
          >
            Check Text
          </button>
          <button
            className={`nav-btn ${tab === "history" ? "active" : ""}`}
            onClick={() => setTab("history")}
          >
            History
          </button>
        </nav>
      </header>

      <main className="main">
        {tab === "checker" ? <Checker /> : <History />}
      </main>

      <footer className="footer">
        <p>Built with React + FastAPI + Groq LLaMA 3 + MySQL</p>
      </footer>
    </div>
  );
}

export default App;
